<script setup lang="ts">
import {money} from '~/shared/types'
const api=useApi(),route=useRoute();const {data:order,error,pending,refresh}=await useAsyncData(()=>`order-${route.params.id}`,()=>api.order(String(route.params.id)))
if(error.value&&(error.value as {statusCode?:number}).statusCode===404)throw createError({statusCode:404,statusMessage:'Заказ не найден'})
useSeoMeta({title:'Тестовый заказ создан — Deadlock Family',robots:'noindex'})
</script>
<template><div class="container page"><ApiState :pending="pending" :error="error" @retry="refresh()"/><div v-if="order" class="order-confirmation"><div class="confirmation-title"><AppIcon name="check" :size="52"/><span class="eyebrow">ЕЩЁ ОДНА ИСТОРИЯ В АРХИВЕ</span><h1>Тестовый заказ создан</h1><p>Номер {{order.number}} · {{new Date(order.createdAt).toLocaleDateString('ru-RU')}}</p><span class="status-pill" style="margin-top:16px">{{order.status}}</span></div><div class="notice success">Сценарий пройден! Средства не списывались, товары не будут отправлены. Этот тестовый заказ доступен в демонстрационной админ-панели текущей сессии.</div><div class="order-items"><div v-for="line in order.items" :key="line.variantId" class="order-line"><span>{{line.name}}<small>{{line.variantLabel}} · {{line.quantity}} шт.</small></span><span>{{money(line.price*line.quantity)}}</span></div><div class="summary-row"><span>Тестовая доставка</span><span>{{money(order.shipping)}}</span></div><div class="summary-total"><span>Итого</span><span>{{money(order.total)}}</span></div></div><div style="text-align:center"><NuxtLink to="/shop" class="btn btn-primary">Продолжить историю <AppIcon name="arrow"/></NuxtLink></div></div></div></template>
